head.script:
scwin.onpageload = function () {
    console.log("테넌트 관리 페이지 로드");
    scwin.loadTenantData();
};

scwin.loadTenantData = function () {
    dmp_tenantVo.set("pageIndex", "1");
    dmp_tenantVo.set("pageSize", "50");

    $c.sbm.execute($p, sbm_selectTenantVoList);
};

scwin.sbm_tenantList_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader == "" || elHeader == "undefined" || elHeader.resSuc == false) {
        alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    console.log("테넌트 데이터 로드 완료:", elData);

    if (elData && elData.tenantVoList) {
        var filteredData = scwin.applyClientSideFilter(elData.tenantVoList);
        dlt_tenantVoList.setJSON(filteredData);
        var totalCount = filteredData.length;
        scwin.updateTenantCount(totalCount);
        scwin.updateTenantDisplay();
    }
};

scwin.applyClientSideFilter = function (dataList) {
    var filterStatus = dmp_tenantVo.get("scStatus");
    if (!filterStatus || filterStatus === "") {
        return dataList; 
    }

    var filteredList = [];
    for (var i = 0; i < dataList.length; i++) {
        var item = dataList[i];
        var itemStatus = String(item.isActive).trim();
        if (filterStatus === "1" && (itemStatus === "1" || itemStatus === "Y")) {
            filteredList.push(item);
        } else if (filterStatus === "0" && (itemStatus === "0" || itemStatus === "N")) {
            filteredList.push(item);
        }
    }
    console.log("필터링 결과:", filterStatus + " 상태로 필터링하여 " + filteredList.length + "개 / " + dataList.length + "개");
    return filteredList;
};

scwin.updateTenantCount = function (count) {
    var countElement = $p.getComponentById("tenant_count");
    if (countElement) {
        countElement.setLabel("테넌트 목록 (" + count + "개)");
    }
};

scwin.updateTenantDisplay = function () {
    try {
        var loadingElement = $p.getComponentById("loading_state");
        if (loadingElement) {
            loadingElement.hide();
        }

        var rowCount = dlt_tenantVoList.getRowCount();
        console.log("총 테넌트 개수:", rowCount);

        scwin.createAllTenantItems(rowCount);

    } catch (e) {
        console.error("테넌트 목록 표시 중 오류:", e);
    }
};

scwin.findContainerElement = function() {
    var possibleSelectors = [
        '#tenant_list_container',
        '#mf_tenant_list_container', 
        '[id$="tenant_list_container"]',
        '.tenant-list',
        '[class*="tenant-list"]'
    ];

    for (var i = 0; i < possibleSelectors.length; i++) {
        var element = document.querySelector(possibleSelectors[i]);
        if (element) {
            console.log("컨테이너 찾음:", possibleSelectors[i], element);
            return element;
        }
    }

    console.error("컨테이너를 찾을 수 없습니다!");
    return null;
};

scwin.createAllTenantItems = function (totalCount) {
    try {
        var containerElement = scwin.findContainerElement();
        if (!containerElement) {
            console.error("컨테이너 요소를 찾을 수 없습니다.");
            return;
        }

        scwin.clearDynamicItems(containerElement);

        containerElement.style.height = 'auto';
        containerElement.style.minHeight = '200px';

        if (totalCount > 0) {
            for (var i = 0; i < totalCount; i++) {
                var tenantData = dlt_tenantVoList.getRowJSON(i);
                scwin.createTenantItemWithDOM(containerElement, tenantData, i);
            }
            console.log(totalCount + "개 테넌트 아이템 생성 완료");

            // 생성 완료 후 컨테이너 높이 재조정
            setTimeout(function() {
                scwin.adjustContainerHeight(containerElement);
            }, 100);
        } else {
            scwin.showNoDataMessage(containerElement);
        }
    } catch (e) {
        console.error("테넌트 아이템 생성 중 오류:", e);
    }
};

scwin.adjustContainerHeight = function(containerElement) {
    try {
        if (containerElement) {
            var totalHeight = 0;
            var children = containerElement.children;

            for (var i = 0; i < children.length; i++) {
                if (children[i].offsetHeight) {
                    totalHeight += children[i].offsetHeight;
                }
            }

            var finalHeight = Math.max(totalHeight + 20, 200); // 20px 여백 추가
            containerElement.style.height = finalHeight + 'px';

            console.log("컨테이너 높이 조정:", finalHeight + 'px');
        }
    } catch (e) {
        console.error("높이 조정 중 오류:", e);
    }
};

scwin.createTenantItemWithDOM = function (containerElement, tenantData, index) {
    try {
        var isActiveValue = String(tenantData.isActive).trim();
        var statusText, statusClass;
        if (isActiveValue === "1" || isActiveValue === "Y" || isActiveValue === "true") {
            statusText = "활성";
            statusClass = "status-active";
        } else {
            statusText = "비활성";
            statusClass = "status-inactive";
        }

        var createdDate = tenantData.createdAt ? tenantData.createdAt.split(' ')[0] : "";

        var userCount = tenantData.userCount || 0;
        var moduleCount = tenantData.moduleCount || 0;

        if (isNaN(userCount)) userCount = 0;
        if (isNaN(moduleCount)) moduleCount = 0;

        var tenantDiv = document.createElement('div');
        tenantDiv.className = 'tenant-item';
        tenantDiv.id = 'dynamic_tenant_' + index;

        tenantDiv.style.cssText = `
            padding: 16px 20px;
            border-bottom: 1px solid #f8f8f8;
            display: block;
            visibility: visible;
            background: white;
            margin-bottom: 2px;
        `;

        tenantDiv.innerHTML = `
            <div class="tenant-name" style="font-size: 16px; font-weight: bold; color: #333; margin-bottom: 8px;">
                ${tenantData.name || 'Unknown'}
            </div>
            <div class="tenant-info" style="font-size: 13px; color: #8e8e93; margin-bottom: 4px;">
                사용자: ${userCount}명 | 모듈: ${moduleCount}개
            </div>
            <div class="tenant-info" style="font-size: 13px; color: #8e8e93; margin-bottom: 4px;">
                서브도메인: ${tenantData.subDomain || 'N/A'} | 생성일: ${createdDate}
            </div>
            <div class="tenant-status ${statusClass}" style="display: inline-block; padding: 4px 12px; border-radius: 12px; font-size: 12px; font-weight: 600; margin-top: 8px; ${statusClass === 'status-active' ? 'background-color: #e6f7e6; color: #34c759;' : 'background-color: #ffe6e6; color: #ff3b30;'}">
                ${statusText}
            </div>
        `;

        containerElement.appendChild(tenantDiv);
        console.log("아이템 생성 성공:", index, tenantData.name, "사용자:", userCount, "모듈:", moduleCount);

    } catch (e) {
        console.error(`DOM 테넌트 아이템 생성 중 오류 발생 (index: ${index})`, e);
    }
};

scwin.clearDynamicItems = function (containerElement) {
    try {
        if (containerElement) {
            var dynamicItems = containerElement.querySelectorAll('[id^="dynamic_tenant_"], #no_data_item, .no-data-message');
            for (var i = 0; i < dynamicItems.length; i++) {
                dynamicItems[i].remove();
            }
            console.log("동적 요소 제거 완료:", dynamicItems.length + "개");
        }
    } catch (e) {
        console.error("동적 요소 제거 중 오류:", e);
    }
};

scwin.showNoDataMessage = function (containerElement) {
    try {
        if (!containerElement) {
            containerElement = scwin.findContainerElement();
        }

        if (containerElement) {
            var existingNoData = containerElement.querySelector('#no_data_item, .no-data-message');
            if (existingNoData) {
                console.log("이미 '데이터 없음' 메시지가 표시되어 있습니다.");
                return;
            }

            var noDataDiv = document.createElement('div');
            noDataDiv.className = 'tenant-item no-data-message';
            noDataDiv.id = 'no_data_item';
            noDataDiv.style.cssText = `
                padding: 40px 20px;
                text-align: center;
                color: #8e8e93;
                font-style: italic;
                display: block;
                visibility: visible;
            `;
            noDataDiv.innerHTML = '<div class="tenant-name">조회된 테넌트가 없습니다.</div>';

            containerElement.appendChild(noDataDiv);

            // 컨테이너 높이 조정
            containerElement.style.height = 'auto';
            containerElement.style.minHeight = '200px';

            console.log("'데이터 없음' 메시지 표시됨");
        }
    } catch (e) {
        console.error("데이터 없음 메시지 표시 중 오류:", e);
    }
};

// 검색 기능
scwin.searchTenant = function () {
    var searchValue = $p.getComponentById("searchInput").getValue().trim();
    dmp_tenantVo.set("scTenantId", "");
    dmp_tenantVo.set("scName", searchValue);
    scwin.loadTenantData();
};

// 필터 기능들
scwin.filterAll = function () {
    dmp_tenantVo.set("scStatus", "");
    scwin.updateFilterButtons("all");
    scwin.loadTenantData();
};

scwin.filterActive = function () {
    dmp_tenantVo.set("scStatus", "1");
    scwin.updateFilterButtons("active");
    scwin.loadTenantData();
};

scwin.filterInactive = function () {
    dmp_tenantVo.set("scStatus", "0");
    scwin.updateFilterButtons("inactive");
    scwin.loadTenantData();
};

// 필터 버튼 상태 업데이트
scwin.updateFilterButtons = function (activeFilter) {
    var allBtn = $p.getComponentById("filter_all");
    var activeBtn = $p.getComponentById("filter_active");
    var inactiveBtn = $p.getComponentById("filter_inactive");

    if (allBtn) allBtn.removeClass("active");
    if (activeBtn) activeBtn.removeClass("active");
    if (inactiveBtn) inactiveBtn.removeClass("active");

    switch (activeFilter) {
        case "all":
            if (allBtn) allBtn.addClass("active");
            break;
        case "active":
            if (activeBtn) activeBtn.addClass("active");
            break;
        case "inactive":
            if (inactiveBtn) inactiveBtn.addClass("active");
            break;
    }
};

// 네비게이션 이벤트들
scwin.btn_home_onclick = function () {
    location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/mobile_dev_dashboard.xml";
};

scwin.btn_tenant_onclick = function () {
    console.log("현재 테넌트 페이지");
};

scwin.btn_module_onclick = function () {
    location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/mobile_dev_module.xml";
};

scwin.btn_stats_onclick = function () {
    location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/mobile_dev_server_info.xml";
};

// 새로고침 기능
scwin.refreshData = function () {
    scwin.loadTenantData();
};
